## Building Your String Tool Library

Five functions. Each solves one string problem. Each is independently useful and can be combined.

### Tool 1: Count Characters

```xiom
fn count_char(text: Str, ch: Char) -> Int {
  let len = string.str_len(text);
  var count = 0;
  var i = 0;
  while i < len {
    if text[i] == ch {
      count = count + 1;
    }
    i = i + 1;
  }
  return count;
}
```

### Tool 2: Reverse Text

```xiom
fn reverse(text: Str) -> Str {
  let len = string.str_len(text);
  var result = "";
  var i = len - 1;
  while i >= 0 {
    result = string.str_concat(result, text[i]);
    i = i - 1;
  }
  return result;
}
```

### Tool 3: Is Blank?

```xiom
fn is_blank(text: Str) -> Bool {
  let len = string.str_len(text);
  if len == 0 {
    return true;
  }
  var i = 0;
  while i < len {
    if text[i] != ' ' {
      return false;
    }
    i = i + 1;
  }
  return true;
}
```

### Tool 4: Starts With "Hello"?

```xiom
fn starts_with_hello(text: Str) -> Bool {
  let len = string.str_len(text);
  if len < 5 {
    return false;
  }
  return text[0] == 'H' and text[1] == 'e' and text[2] == 'l' and text[3] == 'l' and text[4] == 'o';
}
```

### Tool 5: Remove Spaces

```xiom
fn remove_spaces(text: Str) -> Str {
  let len = string.str_len(text);
  var result = "";
  var i = 0;
  while i < len {
    if text[i] != ' ' {
      result = string.str_concat(result, text[i]);
    }
    i = i + 1;
  }
  return result;
}
```

### Testing the Library

```xiom
fn main() -> Int {
  let sample = "Hello World";

  let count_l = count_char(sample, 'l');
  let rev = reverse(sample);
  let blank = is_blank("   ");
  let starts = starts_with_hello(sample);
  let no_spaces = remove_spaces(sample);

  io.println("String library tested!");

  return 0;
